759	static int pwm_stop(struct pwm_lowerhalf_s *dev)
760	{
761	  irqstate_t flags;
762	  struct esp32s3_ledc_s *priv = (struct esp32s3_ledc_s *)dev;
763	
764	  pwminfo("PWM timer%d\n", priv->num);
765	
766	  flags = enter_critical_section();
767	
768	  /* Stop timer */
769	
770	  SET_TIMER_BITS(priv, LEDC_TIMER0_CONF_REG, LEDC_TIMER0_PAUSE);
771	
772	  /* Reset timer */
773	
774	  SET_TIMER_BITS(priv, LEDC_TIMER0_CONF_REG, LEDC_TIMER0_RST);
775	
776	  leave_critical_section(flags);
777	  return 0;
778	}
