218	
219	static int pwm_close(FAR struct file *filep)
220	{
221	  FAR struct inode           *inode = filep->f_inode;
222	  FAR struct pwm_upperhalf_s *upper = inode->i_private;
223	
224	  pwminfo("crefs: %d\n", upper->crefs);
225	
226	  /* Get exclusive access to the device structures */
227	
228	  nxmutex_lock(&upper->lock);
229	
230	  /* Decrement the references to the driver.  If the reference count will
231	   * decrement to 0, then uninitialize the driver.
232	   */
233	
234	  if (upper->crefs > 1)
235	    {
236	      upper->crefs--;
237	    }
238	  else
239	    {
240	      FAR struct pwm_lowerhalf_s *lower = upper->dev;
241	
242	      /* There are no more references to the port */
243	
244	      upper->crefs = 0;
245	
246	      /* Disable the PWM device */
247	
248	      DEBUGASSERT(lower->ops->shutdown != NULL);
249	      pwminfo("calling shutdown\n");
250	
251	      lower->ops->shutdown(lower);
252	    }
253	
254	  nxmutex_unlock(&upper->lock);
255	
256	  return OK;
257	}
