296	
297	#ifdef CONFIG_PWM_PULSECOUNT
298	static int pwm_start(FAR struct pwm_upperhalf_s *upper, unsigned int oflags)
299	{
300	  FAR struct pwm_lowerhalf_s *lower;
301	  irqstate_t flags;
302	  int ret = OK;
303	
304	  DEBUGASSERT(upper != NULL);
305	  lower = upper->dev;
306	  DEBUGASSERT(lower != NULL && lower->ops->start != NULL);
307	
308	  /* Verify that the PWM is not already running */
309	
310	  if (!upper->started)
311	    {
312	      /* Indicate that if will be waiting for the pulse count to complete.
313	       * Note that we will only wait if a non-zero pulse count is specified
314	       * and if the PWM driver was opened in normal, blocking mode.  Also
315	       * assume for now that the pulse train will be successfully started.
316	       *
317	       * We do these things before starting the PWM to avoid race conditions.
318	       */
319	
320	      upper->waiting = (upper->info.count > 0) &&
321	                       ((oflags & O_NONBLOCK) == 0);
322	      upper->started = true;
323	
324	      /* Invoke the bottom half method to start the pulse train */
325	
326	      ret = lower->ops->start(lower, &upper->info, upper);
327	
328	      /* A return value of zero means that the pulse train was started
329	       * successfully.
330	       */
331	
332	      if (ret == OK)
333	        {
334	          /* Should we wait for the pulse output to complete?  Loop in
335	           * in case the wakeup form nxsem_wait() is a false alarm.
336	           */
337	
338	          while (upper->waiting)
339	            {
340	              /* Wait until we are awakened by pwm_expired().  When
341	               * pwm_expired is called, it will post the waitsem and
342	               * clear the waiting flag.
343	               */
344	
345	              ret = nxsem_wait_uninterruptible(&upper->waitsem);
346	              if (ret < 0)
347	                {
348	                  upper->started = false;
349	                  upper->waiting = false;
350	                }
351	            }
352	        }
353	      else
354	        {
355	          /* Looks like we won't be waiting after all */
356	
357	          pwminfo("start failed: %d\n", ret);
358	          upper->started = false;
359	          upper->waiting = false;
360	        }
361	    }
362	
363	  return ret;
364	}
