399	/****************************************************************************
400	 * Name: pwm_ioctl
401	 *
402	 * Description:
403	 *   The standard ioctl method.  This is where ALL of the PWM work is done.
404	 *
405	 ****************************************************************************/
406	
407	static int pwm_ioctl(FAR struct file *filep, int cmd, unsigned long arg)
408	{
409	  FAR struct inode           *inode = filep->f_inode;
410	  FAR struct pwm_upperhalf_s *upper = inode->i_private;
411	  FAR struct pwm_lowerhalf_s *lower = upper->dev;
412	  int ret                           = OK;
413	
414	  pwminfo("cmd: %d arg: %ld\n", cmd, arg);
415	
416	  /* Get exclusive access to the device structures */
417	
418	  nxmutex_lock(&upper->lock);
419	
420	  /* Handle built-in ioctl commands */
421	
422	  switch (cmd)
423	    {
424	      /* PWMIOC_SETCHARACTERISTICS - Set the characteristics of the next
425	       *   pulsed output and start the pulsed output. It will change the
426	       *   characteristics of the pulsed output on the fly if the timer is
427	       *   already started.
428	       *
429	       *   ioctl argument:  A read-only reference to struct pwm_info_s that
430	       *   provides the characteristics of the pulsed output.
431	       */
432	
433	      case PWMIOC_SETCHARACTERISTICS:
434	        {
435	          FAR const struct pwm_info_s *info =
436	            (FAR const struct pwm_info_s *)((uintptr_t)arg);
437	          DEBUGASSERT(info != NULL && lower->ops->start != NULL);
438	
439	          pwm_dump("PWMIOC_SETCHARACTERISTICS", info, upper->started);
440	
441	          /* Save the pulse train characteristics */
442	
443	          memcpy(&upper->info, info, sizeof(struct pwm_info_s));
444	
445	          /* If PWM is already running, then re-start it with the new
446	           * characteristics.
447	           */
448	
449	          if (upper->started)
450	            {
451	#ifdef CONFIG_PWM_PULSECOUNT
452	              ret = lower->ops->start(lower, &upper->info, upper);
453	#else
454	              ret = lower->ops->start(lower, &upper->info);
455	#endif
456	            }
457	        }
458	        break;
459	
460	      /* PWMIOC_GETCHARACTERISTICS - Get the currently selected
461	       * characteristics of the pulsed output (independent of whether the
462	       * output is start or stopped).
463	       *
464	       *   ioctl argument:  A reference to struct pwm_info_s to receive the
465	       *   characteristics of the pulsed output.
466	       */
467	
468	      case PWMIOC_GETCHARACTERISTICS:
